/* Solo los paises donde de verdad se puede contar algo. La portada y la
   pantalla de partidos leen de aqui para no prometer barras imposibles. */
EH.PAISES_CON_CONTADOR = EH.RUTA_ELECTORAL.filter(function (p) {
  return p.contadorPosible && p.requisitoCantidad > 0;
});

EH.rutaDe = function (id) {
  return EH.RUTA_ELECTORAL.filter(function (p) { return p.id === id; })[0] || null;
};

